#nullable enable // autogenerated

using MVZ2.Vanilla.Enemies;
using MVZ2.Vanilla.Entities;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.axolotlSuit_State)]
    public class AxolotlSuit_StateBehaviour : EnemyStateBehaviour
    {
        public AxolotlSuit_StateBehaviour(string nsp, string name) : base(nsp, name)
        {
        }
        protected override int GetPassiveState(Entity enemy)
        {
            var state = base.GetPassiveState(enemy);
            if (state >= 0)
                return state;
            if (AxolotlSuit.IsEmpty(enemy))
                return STATE_EMPTY;
            if (AxolotlSuit.IsBeingEntered(enemy))
                return STATE_ENTERED;
            return -1;
        }
        public const int STATE_EMPTY = VanillaEnemyStates.AXOLOTL_SUIT_EMPTY;
        public const int STATE_ENTERED = VanillaEnemyStates.AXOLOTL_SUIT_BEING_ENTERED;
    }
}
